			</div>
		</div>
	);
}

import React, { useEffect, useRef, useState } from 'react';
import { Grid, duplicateValueRule } from '@eregister/wit-grid-react';
import type { ColumnDef, GridReadyEvent, GridApi, GridTransactionStreamHandle, GridIntegrityIssue, GridDiffModel } from '@eregister/wit-grid-react';

// ── Data model ────────────────────────────────────────────────────────────────

interface TradeRow {
	id: string;
	symbol: string;
	trader: string;
	quantity: number;
	price: number;
	notional: number;
	status: 'OPEN' | 'FILLED' | 'CANCELLED' | 'REJECTED';
	desk: string;
	venue: string;
}

const SYMBOLS = ['AAPL', 'MSFT', 'NVDA', 'TSLA', 'AMZN', 'GOOGL', 'META', 'JPM'];
const TRADERS = ['Alice', 'Bob', 'Carol', 'Dave', 'Eve', 'Frank'];
const DESKS = ['Equity', 'Fixed Income', 'Derivatives', 'FX'];
const VENUES = ['NYSE', 'NASDAQ', 'CBOE', 'LSE'];
const STATUSES: TradeRow['status'][] = ['OPEN', 'FILLED', 'CANCELLED', 'REJECTED'];

function makeRow(i: number): TradeRow {
	const symbol = SYMBOLS[i % SYMBOLS.length];
	const qty = 100 + ((i * 37) % 900);
	const price = parseFloat((50 + ((i * 13) % 400)).toFixed(2));
	return {
		id: `T${String(i + 1).padStart(4, '0')}`,
		symbol,
		trader: TRADERS[i % TRADERS.length],
		quantity: qty,
		price,
		notional: qty * price,
		status: STATUSES[i % STATUSES.length],
		desk: DESKS[i % DESKS.length],
		venue: VENUES[i % VENUES.length],
	};
}

const BASE_ROWS: TradeRow[] = Array.from({ length: 30 }, (_, i) => makeRow(i));

// ── Compare dataset (slightly different from base) ────────────────────────────

function makeCompareRows(): TradeRow[] {
	return BASE_ROWS.map((r, i) => {
		if (i % 5 === 0)
			return { ...r, price: parseFloat((r.price * 1.05).toFixed(2)), notional: r.quantity * parseFloat((r.price * 1.05).toFixed(2)) };
		if (i % 7 === 0) return { ...r, status: 'CANCELLED' as const };
		return r;
	}).filter((_, i) => i !== 3); // simulate one removed row
}

// ── Columns ───────────────────────────────────────────────────────────────────

function StatusRenderer({ value }: { value: unknown }) {
	const color: Record<string, string> = {
		OPEN: '#22c55e',
		FILLED: '#6366f1',
		CANCELLED: '#f59e0b',
		REJECTED: '#ef4444',
	};
	const v = String(value ?? '');
	return (
		<span
			style={{
				fontSize: 10,
				fontWeight: 700,
				padding: '2px 7px',
				borderRadius: 4,
				background: `${color[v] ?? '#6b7280'}22`,
				color: color[v] ?? '#6b7280',
			}}
		>
			{v}
		</span>
	);
}

const COLUMNS: ColumnDef<TradeRow>[] = [
	{ field: 'id', header: 'Trade ID', width: 90 },
	{ field: 'symbol', header: 'Symbol', width: 80 },
	{ field: 'trader', header: 'Trader', width: 90 },
	{ field: 'desk', header: 'Desk', width: 100 },
	{ field: 'venue', header: 'Venue', width: 80 },
	{ field: 'quantity', header: 'Qty', width: 80, type: 'number' },
	{
		field: 'price',
		header: 'Price',
		width: 90,
		type: 'number',
		valueFormatter: (p) => (p.value != null ? `$${Number(p.value).toFixed(2)}` : ''),
	},
	{
		field: 'notional',
		header: 'Notional',
		width: 110,
		type: 'number',
		valueFormatter: (p) => (p.value != null ? `$${Number(p.value).toLocaleString()}` : ''),
	},
	{
		field: 'status',
		header: 'Status',
		width: 95,
		renderer: { kind: 'react', component: StatusRenderer },
	},
];

// ── Panel button style ────────────────────────────────────────────────────────

type BtnVariant = 'primary' | 'amber' | 'green' | 'red' | 'indigo' | 'ghost';

function Btn({
	children,
	onClick,
	variant = 'ghost',
	disabled,
}: {
	children: React.ReactNode;
	onClick?: () => void;
	variant?: BtnVariant;
	disabled?: boolean;
}) {
	const colors: Record<BtnVariant, string> = {
		primary: 'bg-purple-600/20 border-purple-500/40 text-purple-300 hover:bg-purple-600/30',
		amber: 'bg-amber-500/20 border-amber-500/40 text-amber-300 hover:bg-amber-500/30',
		green: 'bg-emerald-500/20 border-emerald-500/40 text-emerald-300 hover:bg-emerald-500/30',
		red: 'bg-red-500/20 border-red-500/40 text-red-300 hover:bg-red-500/30',
		indigo: 'bg-indigo-500/20 border-indigo-500/40 text-indigo-300 hover:bg-indigo-500/30',
		ghost: 'bg-slate-800/40 border-slate-700/40 text-slate-400 hover:text-slate-200 hover:bg-slate-800/60',
	};
	return (
		<button
			onClick={onClick}
			disabled={disabled}
			className={`px-2.5 py-1 rounded-lg border text-[10px] font-bold uppercase tracking-wide transition-all ${colors[variant]} disabled:opacity-40 disabled:cursor-not-allowed`}
		>
			{children}
		</button>
	);
}

// ── Stage badge ───────────────────────────────────────────────────────────────

function StageBadge({ label, active, done }: { label: string; active: boolean; done: boolean }) {
	return (
		<div
			className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg border text-[10px] font-bold uppercase tracking-wide transition-all ${
				done
					? 'border-emerald-500/30 bg-emerald-500/10 text-emerald-400'
					: active
						? 'border-purple-500/50 bg-purple-500/15 text-purple-300'
						: 'border-slate-800 bg-slate-900/20 text-slate-600'
			}`}
		>
			{done ? '✓' : active ? '◉' : '○'} {label}
		</div>
	);
}

// ── Main component ────────────────────────────────────────────────────────────

type Stage = 'quality' | 'diff' | 'stream' | 'conflict';

interface Props {
	/** Hides the Activity Log panel, keeping just the stage controls and grid. */
	compact?: boolean;
}

export default function DataIntegrityLab({ compact = false }: Props = {}) {
	const apiRef = useRef<GridApi<TradeRow> | null>(null);
	const streamRef = useRef<GridTransactionStreamHandle<TradeRow> | null>(null);
	const [activeStage, setActiveStage] = useState<Stage>('quality');
	const [log, setLog] = useState<string[]>([]);
	const [qualityIssues, setQualityIssues] = useState<GridIntegrityIssue[] | null>(null);
	const [diffActive, setDiffActive] = useState(false);
	const [streamRunning, setStreamRunning] = useState(false);
	const [conflictCount, setConflictCount] = useState(0);

	function addLog(msg: string) {
		setLog((prev) => [`[${new Date().toLocaleTimeString('en-US', { hour12: false })}] ${msg}`, ...prev].slice(0, 40));
	}

	function onGridReady(e: GridReadyEvent<TradeRow>) {
		const api = e.api as GridApi<TradeRow>;
		apiRef.current = api;
		addLog('Grid ready — 30 trade rows loaded');
	}

	// ── Stage 1: Data Quality ─────────────────────────────────────────────────

	async function handleRunQuality() {
		const api = apiRef.current;
		if (!api) return;
		addLog('Running data quality check…');
		const result = await api.integrity.run({ modules: ['quality'] });
		const issues = result.issues.filter((i) => i.source === 'dataQuality') as GridIntegrityIssue[];
		setQualityIssues(issues);
		addLog(
			`Quality: ${issues.length} issues found (${issues.filter((i) => i.severity === 'error').length} errors, ${issues.filter((i) => i.severity === 'warning').length} warnings)`
		);
	}

	function handleClearQuality() {
		apiRef.current?.integrity.clearIssues({ source: 'dataQuality' });
		setQualityIssues(null);
		addLog('Quality report cleared');
	}

	// ── Stage 2: Data Diff ────────────────────────────────────────────────────

	function handleActivateDiff() {
		const api = apiRef.current;
		if (!api) return;
		const compareRows = makeCompareRows();
		const model: GridDiffModel<TradeRow> = {
			base: { rows: BASE_ROWS, getRowId: (r) => r.id },
			compare: { rows: compareRows, getRowId: (r) => r.id },
		};
		api.integrity.setDiffModel(model);
		setDiffActive(true);
		addLog('Diff activated — comparing current vs EOD snapshot');
	}

	function handleClearDiff() {
		apiRef.current?.integrity.clearDiff();
		setDiffActive(false);
		addLog('Diff cleared');
	}

	// ── Stage 3: Live Stream ──────────────────────────────────────────────────

	function handleStartStream() {
		const api = apiRef.current;
		if (!api || streamRef.current) return;
		const stream = api.integrity.createStream({
			batchMs: 400,
			flashChanges: true,
			coalesceBy: 'cell',
			dirtyCellPolicy: 'markConflict',
		});
		streamRef.current = stream;
		setStreamRunning(true);
		addLog('Live stream started — price updates every 400ms');

		let tick = 0;
		function pushTick() {
			if (!streamRef.current) return;
			const rows = BASE_ROWS;
			const n = 3 + (tick % 4);
			const updates = Array.from({ length: n }, () => {
				const row = rows[Math.floor(Math.abs(Math.sin(tick * 7 + Math.random())) * rows.length)];
				const newPrice = parseFloat((row.price * (0.98 + Math.random() * 0.04)).toFixed(2));
				tick++;
				return { rowId: row.id, colField: 'price', value: newPrice };
			});
			stream.push({ cells: updates });
			setTimeout(pushTick, 600 + Math.floor(Math.random() * 400));
		}
		pushTick();
	}

	function handleStopStream() {
		streamRef.current?.destroy();
		streamRef.current = null;
		setStreamRunning(false);
		addLog('Live stream stopped');
	}

	// ── Stage 4: Conflicts ────────────────────────────────────────────────────

	function handleInjectConflicts() {
		const api = apiRef.current;
		if (!api) return;
		const now = Date.now();
		const conflictIssues: GridIntegrityIssue[] = [
			{
				id: 'ci-T0001-price',
				source: 'conflict',
				type: 'conflict',
				severity: 'error',
				blocking: true,
				rowId: 'T0001',
				colField: 'price',
				message: 'Conflict: local 65.5 vs remote 61.0',
				createdAt: now,
			},
			{
				id: 'ci-T0003-status',
				source: 'conflict',
				type: 'conflict',
				severity: 'error',
				blocking: true,
				rowId: 'T0003',
				colField: 'status',
				message: 'Conflict: local FILLED vs remote CANCELLED',
				createdAt: now,
			},
			{
				id: 'ci-T0007-qty',
				source: 'conflict',
				type: 'conflict',
				severity: 'error',
				blocking: true,
				rowId: 'T0007',
				colField: 'quantity',
				message: 'Conflict: local 850 vs remote 750',
				createdAt: now,
			},
		];
		api.integrity.publishIssues('conflict', conflictIssues);
		setConflictCount(3);
		addLog(`Injected 3 conflicts — open Conflicts panel to resolve`);
	}

	function handleResolveAll() {
		const api = apiRef.current;
		if (!api) return;
		api.integrity.clearIssues({ source: 'conflict' });
		setConflictCount(0);
		addLog('All conflicts cleared');
	}

	// ── Cleanup on unmount ────────────────────────────────────────────────────

	useEffect(() => {
		return () => {
			streamRef.current?.destroy();
			streamRef.current = null;
		};
	}, []);

	const stages: { id: Stage; label: string }[] = [
		{ id: 'quality', label: '1 · Quality' },
		{ id: 'diff', label: '2 · Diff' },
		{ id: 'stream', label: '3 · Stream' },
		{ id: 'conflict', label: '4 · Conflicts' },
	];

	const stageDone: Record<Stage, boolean> = {
		quality: qualityIssues !== null,
		diff: diffActive,
		stream: streamRunning,
		conflict: conflictCount === 0 && false, // never "done" automatically
	};

	return (
		<div className='flex h-full min-h-0 flex-col gap-3 overflow-hidden'>
			{/* Top control strip */}
			<div className='flex flex-col gap-2 rounded-xl border border-slate-800/60 bg-slate-900/30 p-3'>
				{/* Stage breadcrumb */}
				<div className='flex items-center gap-2 flex-wrap'>
					{stages.map((s) => (
						<button key={s.id} onClick={() => setActiveStage(s.id)}>
							<StageBadge label={s.label} active={activeStage === s.id} done={stageDone[s.id]} />
						</button>
					))}
					<div className='ml-auto text-[9px] font-bold uppercase tracking-widest text-slate-600'>Data Integrity Pipeline</div>
				</div>

				{/* Stage controls */}
				<div className='flex items-center gap-2 flex-wrap min-h-[28px]'>
					{activeStage === 'quality' && (
						<>
							<Btn variant='primary' onClick={handleRunQuality}>
								Run Quality Check
							</Btn>
							{qualityIssues !== null && (
								<>
									<span className='text-[10px] text-slate-400'>
										{qualityIssues.length} issues —{' '}
										<span className='text-red-400'>{qualityIssues.filter((i) => i.severity === 'error').length} errors</span>{' '}
										<span className='text-amber-400'>
											{qualityIssues.filter((i) => i.severity === 'warning').length} warnings
										</span>
									</span>
									<Btn onClick={handleClearQuality}>Clear</Btn>
								</>
							)}
						</>
					)}
					{activeStage === 'diff' && (
						<>
							{!diffActive ? (
								<Btn variant='amber' onClick={handleActivateDiff}>
									Activate EOD Diff
								</Btn>
							) : (
								<Btn onClick={handleClearDiff}>Clear Diff</Btn>
							)}
							<span className='text-[10px] text-slate-500'>
								Compares live data vs EOD snapshot — changed cells highlighted amber, removed rows red
							</span>
						</>
					)}
					{activeStage === 'stream' && (
						<>
							{!streamRunning ? (
								<Btn variant='green' onClick={handleStartStream}>
									Start Live Feed
								</Btn>
							) : (
								<Btn variant='red' onClick={handleStopStream}>
									Stop Feed
								</Btn>
							)}
							<span className='text-[10px] text-slate-500'>
								{streamRunning
									? 'Streaming price updates — cells flash yellow on update'
									: 'Click to stream live price ticks with coalescing & flash'}
							</span>
						</>
					)}
					{activeStage === 'conflict' && (
						<>
							<Btn variant='indigo' onClick={handleInjectConflicts} disabled={conflictCount > 0}>
								Inject 3 Conflicts
							</Btn>
							{conflictCount > 0 && (
								<>
									<span className='text-[10px] text-red-400'>{conflictCount} unresolved conflicts (striped cells)</span>
									<Btn variant='red' onClick={handleResolveAll}>
										Clear All
									</Btn>
								</>
							)}
							{conflictCount === 0 && (
								<span className='text-[10px] text-slate-500'>
									Injects server-vs-local conflicts; open Conflicts panel to resolve per-cell
								</span>
							)}
						</>
					)}
				</div>
			</div>

			{/* Grid + log */}
			<div className='flex min-h-0 flex-1 gap-3 overflow-hidden'>
				{/* Grid */}
				<div className='flex-1 min-w-0 demo-grid-surface rounded-xl border border-slate-800/60 overflow-hidden'>
					<Grid<TradeRow>
						columns={COLUMNS}
						rows={BASE_ROWS}
						getRowId={(r) => r.id}
						dataIntegrity={{
							quality: {
								enabled: true,
								rules: [
									duplicateValueRule('symbol'),
									{
										id: 'notional-range',
										label: 'Notional Range',
										run(context) {
											return context.rows
												.filter((ref) => {
													const n = (ref.row as TradeRow).notional;
													return n < 5_000 || n > 500_000;
												})
												.map((ref) => ({
													id: `notional-range-${ref.rowId}`,
													source: 'dataQuality' as const,
													type: 'custom' as const,
													severity: 'error' as const,
													blocking: false,
													rowId: ref.rowId,
													colField: 'notional',
													message: `Notional out of [$5k – $500k]`,
													createdAt: Date.now(),
												}));
										},
									},
								],
							},
							diff: true,
							liveStream: { enabled: true, dirtyCellPolicy: 'markConflict', flashChanges: true },
							conflicts: true,
						}}
						sidebar={{
							panels: ['columns', 'dataIntegrity'],
							position: 'right',
						}}
						onGridReady={onGridReady}
					/>
				</div>

				{/* Activity log */}
				{!compact && (
					<div className='w-52 shrink-0 rounded-xl border border-slate-800/60 bg-slate-900/30 flex flex-col overflow-hidden'>
						<div className='flex items-center justify-between px-3 py-2 border-b border-slate-800/60'>
							<span className='text-[9px] font-extrabold uppercase tracking-widest text-slate-500'>Activity Log</span>
							{log.length > 0 && (
								<button onClick={() => setLog([])} className='text-[9px] text-slate-600 hover:text-slate-400'>
									Clear
								</button>
							)}
						</div>
						<div className='flex-1 overflow-y-auto flex flex-col-reverse p-2 gap-1'>
							{log.length === 0 ? (
								<p className='text-[9px] text-slate-700 text-center mt-4'>No activity yet</p>
							) : (
								log.map((msg, i) => (
									<div key={i} className='text-[9px] text-slate-400 font-mono leading-tight'>
										{msg}
									</div>
								))
							)}
						</div>
					</div>
				)}
			</div>
		</div>
	);
}

/**
 * Markets Desk — a high-frequency live markets dashboard on Wit Grid.
 *
 * A seeded universe of 10k / 50k / 200k instruments (5k in `compact`) ticks through a random-walk feed:
 * ticks accumulate and land as ONE `api.transaction({ rows: { update } })` per animation frame.
 * The grid is grouped (asset class › sector), sticky-headed, aggregated, sorted live by change %,
 * and drawn with DOM renderers (price flash, sparkline, heat bar, day range, P&L bar, gauges),
 * React cells for low-frequency badges, and a custom group renderer. A telemetry panel measures
 * the grid honestly (transaction wall time, frame time, dropped frames, long tasks) and mirrors
 * the numbers on `window.__marketsDeskTelemetry`.
 *
 * Theme-aware: `theme="light"` uses the built-in `'spreadsheet'` grid theme and re-tints the cells
 * through CSS variables. Defaults to `'dark'` for hosts (like the demo app) that don't pass it.
 *
 * Files: ./marketsDesk/{data, feed, telemetry, columns, domRenderers, reactCells, panels, DeskGrid, styles}.
 */
'use client';

import React, { useCallback, useEffect, useRef, useState } from 'react';
import type { GridReadyEvent, RowAnimationOptions } from '@eregister/wit-grid-react';
import { Pause, Play, TrendingUp } from 'lucide-react';
import { DeskGrid, type GroupBy, type GroupDisplay } from './marketsDesk/DeskGrid';
import { generateMarketAsync, type MarketRow } from './marketsDesk/data';
import { FeedEngine } from './marketsDesk/feed';
import { KpiStrip, PnlChart, SectorHeatmap, TelemetryBadge, TelemetryPanel } from './marketsDesk/panels';
import { DESK_CSS } from './marketsDesk/styles';

export type { MarketRow } from './marketsDesk/data';

interface RealtimeDashboardProps {
	editTrigger?: 'singleClick' | 'doubleClick';
	arrowKeyNavigationEdit?: boolean;
	onCellValueChanged?: (event: { rowId: string; colField: string; oldValue: unknown; newValue: unknown }) => void;
	onGridReady?: (event: GridReadyEvent<MarketRow>) => void;
	/**
	 * Landing-page layout: 5k rows grouped by asset class, a KPI strip, a one-line telemetry badge
	 * and the grid; the heatmap, P&L chart and telemetry panel are left out.
	 */
	compact?: boolean;
	/**
	 * Light switches the grid to the built-in `'spreadsheet'` theme and re-tints this component's own
	 * chrome and custom renderers to match. Defaults to `'dark'`.
	 */
	theme?: 'light' | 'dark';
	/** Initial instrument count. Default: 50,000 (5,000 in `compact`). The gauntlet passes a small number. */
	rowCount?: number;
	/** Initial updates per second (100 / 1,000 / 10,000 / 50,000). Default: 10,000 (1,000 in `compact`). */
	rate?: number;
	/** Start with the feed paused. */
	paused?: boolean;
}

/** Row animation styles to try on the live sort: each is a plain `rowAnimation` object. */
export const ROW_ANIMATION_PRESETS = {
	cascade: { label: 'Cascade', options: { style: 'slide', easing: 'snappy', duration: 360, stagger: 18 } },
	spring: { label: 'Spring', options: { style: 'slide', easing: 'spring', duration: 520 } },
	smooth: { label: 'Smooth', options: { style: 'slide', easing: 'smooth', duration: 280 } },
	fade: { label: 'Fade', options: { style: 'fade', duration: 320, stagger: 12 } },
	off: { label: 'Off', options: { style: 'none' } },
} satisfies Record<string, { label: string; options: RowAnimationOptions }>;

type PresetId = keyof typeof ROW_ANIMATION_PRESETS;
const PRESET_IDS = Object.keys(ROW_ANIMATION_PRESETS) as PresetId[];

const ROW_COUNTS = [
	{ value: 10_000, label: '10k' },
	{ value: 50_000, label: '50k' },
	{ value: 200_000, label: '200k' },
];
const RATES = [
	{ value: 100, label: '100' },
	{ value: 1_000, label: '1k' },
	{ value: 10_000, label: '10k' },
	{ value: 50_000, label: '50k' },
];
const GROUPINGS: { value: GroupBy; label: string }[] = [
	{ value: 'none', label: 'None' },
	{ value: 'class', label: 'Class' },
	{ value: 'sector', label: 'Class › Sector' },
	{ value: 'region', label: 'Class › Sector › Region' },
];
const DISPLAYS: { value: GroupDisplay; label: string }[] = [
	{ value: 'column', label: 'Column' },
	{ value: 'row', label: 'Row' },
];

function Segmented<T extends string | number>({
	label,
	value,
	options,
	onChange,
	isLight,
	title,
}: {
	label: string;
	value: T;
	options: { value: T; label: string }[];
	onChange: (value: T) => void;
	isLight: boolean;
	title?: string;
}) {
	return (
		<div
			role='radiogroup'
			aria-label={label}
			title={title ?? label}
			className={`flex shrink-0 items-center gap-0.5 rounded-lg border p-0.5 ${isLight ? 'border-slate-300 bg-slate-100' : 'border-slate-700/60 bg-slate-900/80'}`}
		>
			<span className='px-1.5 text-[9px] font-bold uppercase tracking-wider text-slate-500'>{label}</span>
			{options.map((o) => {
				const active = o.value === value;
				return (
					<button
						key={String(o.value)}
						type='button'
						role='radio'
						aria-checked={active}
						onClick={() => onChange(o.value)}
						className={`cursor-pointer rounded-md px-2 py-1 text-[10px] font-bold transition-colors ${
							active
								? 'bg-indigo-600 text-white shadow-sm shadow-indigo-900/30'
								: isLight
									? 'text-slate-600 hover:bg-slate-200 hover:text-slate-900'
									: 'text-slate-400 hover:bg-slate-800 hover:text-slate-100'
						}`}
					>
						{o.label}
					</button>
				);
			})}
		</div>
	);
}

export default function RealtimeDashboard({
	editTrigger = 'doubleClick',
	arrowKeyNavigationEdit = true,
	onCellValueChanged,
	onGridReady,
	compact = false,
	theme = 'dark',
	rowCount: rowCountProp,
	rate: rateProp,
	paused: pausedProp,
}: RealtimeDashboardProps = {}) {
	const isLight = theme === 'light';
	const [rowCount, setRowCount] = useState(rowCountProp ?? (compact ? 5_000 : 50_000));
	const [rate, setRate] = useState(rateProp ?? (compact ? 1_000 : 10_000));
	const [paused, setPaused] = useState(pausedProp ?? false);
	const [groupBy, setGroupBy] = useState<GroupBy>(compact ? 'class' : 'sector');
	const [display, setDisplay] = useState<GroupDisplay>('column');
	const [preset, setPreset] = useState<PresetId>('cascade');
	const [sectorFilter, setSectorFilter] = useState<string | null>(null);
	const [engine, setEngine] = useState<FeedEngine | null>(null);
	const engineRef = useRef<FeedEngine | null>(null);
	// The universe being built for a new row count (the current one keeps running until it is ready).
	const [building, setBuilding] = useState<{ count: number; done: number } | null>(null);

	// A new row count builds its universe in slices (the page stays responsive, progress shows), then
	// swaps it into the same grid; the old feed runs until then.
	useEffect(() => {
		const controller = new AbortController();
		let lastProgressAt = 0;
		setBuilding({ count: rowCount, done: 0 });
		generateMarketAsync(rowCount, {
			signal: controller.signal,
			onProgress: (done) => {
				const now = performance.now();
				if (now - lastProgressAt < 100) return;
				lastProgressAt = now;
				setBuilding({ count: rowCount, done });
			},
		})
			.then((rows) => {
				if (controller.signal.aborted) return;
				const created = new FeedEngine(rowCount, 2026, rows);
				created.start();
				const previous = engineRef.current;
				engineRef.current = created;
				setEngine(created);
				setBuilding(null);
				previous?.dispose();
			})
			.catch((error: unknown) => {
				if ((error as { name?: string })?.name !== 'AbortError') throw error;
			});
		return () => controller.abort();
	}, [rowCount]);

	useEffect(
		() => () => {
			engineRef.current?.dispose();
			engineRef.current = null;
		},
		[]
	);

	useEffect(() => {
		engine?.setRate(rate);
		engine?.setPaused(paused);
	}, [engine, rate, paused]);

	// Host callbacks may change identity each render; the memoised grid reads them through refs.
	const hostRef = useRef({ onCellValueChanged, onGridReady });
	hostRef.current = { onCellValueChanged, onGridReady };
	const handleCellValueChanged = useCallback<NonNullable<RealtimeDashboardProps['onCellValueChanged']>>(
		(e) => hostRef.current.onCellValueChanged?.(e),
		[]
	);
	const handleGridReady = useCallback((e: GridReadyEvent<MarketRow>) => hostRef.current.onGridReady?.(e), []);

	const ui = isLight
		? { shell: 'bg-white', bar: 'border-slate-200 bg-slate-50', title: 'text-slate-600', dot: 'bg-emerald-600', icon: 'text-emerald-600' }
		: { shell: '', bar: 'border-slate-900 bg-slate-900/10', title: 'text-slate-400', dot: 'bg-emerald-500', icon: 'text-emerald-400' };

	const pauseButton = (
		<button
			type='button'
			onClick={() => setPaused((p) => !p)}
			className={`flex shrink-0 cursor-pointer items-center gap-1.5 rounded-lg border px-3 py-1.5 text-[10px] font-bold transition-colors ${
				paused
					? 'border-emerald-500/30 bg-emerald-600 text-white hover:bg-emerald-700'
					: isLight
						? 'border-slate-300 bg-slate-100 text-slate-700 hover:bg-slate-200'
						: 'border-slate-700/60 bg-slate-800 text-slate-300 hover:bg-slate-700'
			}`}
		>
			{paused ? <Play className='h-3 w-3' /> : <Pause className='h-3 w-3' />}
			{paused ? 'Resume feed' : 'Pause feed'}
		</button>
	);

	const motion = (
		<Segmented
			label='Motion'
			title='How rows move when the live sort reorders them'
			isLight={isLight}
			value={preset}
			onChange={setPreset}
			options={PRESET_IDS.map((id) => ({ value: id, label: ROW_ANIMATION_PRESETS[id].label }))}
		/>
	);

	return (
		<div className={`md-root ${isLight ? 'md-light' : 'md-dark'} flex h-full w-full min-w-0 flex-col gap-2 overflow-hidden ${ui.shell}`}>
			<style>{DESK_CSS}</style>

			<div className={`flex shrink-0 flex-wrap items-center gap-x-3 gap-y-2 rounded-xl border p-2 ${ui.bar}`}>
				<span className={`flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-wider ${ui.title}`}>
					<span className={`h-2 w-2 rounded-full ${paused ? 'bg-slate-500' : `animate-ping ${ui.dot}`}`} />
					<TrendingUp className={`h-4 w-4 ${ui.icon}`} />
					Markets desk
				</span>
				<Segmented label='Rate' title='Price updates per second' isLight={isLight} value={rate} onChange={setRate} options={RATES} />
				{!compact && (
					<Segmented label='Rows' title='Instrument count' isLight={isLight} value={rowCount} onChange={setRowCount} options={ROW_COUNTS} />
				)}
				{!compact && <Segmented label='Group' isLight={isLight} value={groupBy} onChange={setGroupBy} options={GROUPINGS} />}
				{!compact && groupBy !== 'none' && (
					<Segmented label='Display' isLight={isLight} value={display} onChange={setDisplay} options={DISPLAYS} />
				)}
				<div className='ml-auto flex flex-wrap items-center gap-2'>
					<div className={compact ? 'hidden md:block' : ''}>{motion}</div>
					{pauseButton}
					{compact && engine && <TelemetryBadge engine={engine} isLight={isLight} />}
				</div>
			</div>

			{engine ? (
				<>
					<KpiStrip engine={engine} isLight={isLight} compact={compact} />
					{!compact && (
						<div className='hidden h-[132px] shrink-0 gap-2 md:flex'>
							<SectorHeatmap engine={engine} isLight={isLight} selected={sectorFilter} onSelect={setSectorFilter} />
							<PnlChart engine={engine} isLight={isLight} />
							<TelemetryPanel engine={engine} isLight={isLight} />
						</div>
					)}
					<div className='relative min-h-[260px] min-w-0 flex-1'>
						{building && <BuildingBadge building={building} isLight={isLight} />}
						<DeskGrid
							engine={engine}
							display={display}
							groupBy={groupBy}
							isLight={isLight}
							compact={compact}
							sectorFilter={sectorFilter}
							rowAnimation={ROW_ANIMATION_PRESETS[preset].options}
							editTrigger={editTrigger}
							arrowKeyNavigationEdit={arrowKeyNavigationEdit}
							onCellValueChanged={handleCellValueChanged}
							onGridReady={handleGridReady}
						/>
					</div>
				</>
			) : (
				<div className={`flex flex-1 items-center justify-center text-xs ${ui.title}`}>
					Generating {rowCount.toLocaleString('en-US')} instruments…{' '}
					{building ? `${Math.round((building.done / building.count) * 100)}%` : ''}
				</div>
			)}
		</div>
	);
}

/** Over the live grid while the next universe builds: the current one stays interactive until the swap. */
function BuildingBadge({ building, isLight }: { building: { count: number; done: number }; isLight: boolean }) {
	const pct = Math.round((building.done / building.count) * 100);
	return (
		<div
			role='status'
			className={`pointer-events-none absolute left-1/2 top-3 z-20 flex -translate-x-1/2 items-center gap-2 rounded-full border px-3 py-1.5 text-[11px] font-semibold shadow-lg ${
				isLight ? 'border-slate-200 bg-white/95 text-slate-700' : 'border-slate-700/70 bg-slate-900/95 text-slate-200'
			}`}
		>
			<span className='relative h-1.5 w-16 overflow-hidden rounded-full bg-slate-500/25'>
				<span
					className='absolute inset-y-0 left-0 rounded-full bg-emerald-500 transition-[width] duration-150'
					style={{ width: `${pct}%` }}
				/>
			</span>
			Preparing {building.count.toLocaleString('en-US')} instruments · {pct}%
		</div>
	);
}

/**
 * Kanban Board Demo — variable-height rows
 *
 * Compares two approaches side-by-side via a toggle:
 *   - getRowHeight   — pre-computed heights from data, zero DOM cost
 *   - autoRowHeight  — measured from scrollHeight after first paint, zero manual math
 *
 * Rich cell renderers used:
 *   - Priority badge cell  — colour-coded severity pill
 *   - Progress arc cell    — SVG arc showing % complete
 *   - Tag cloud cell       — wrapping coloured label chips
 *   - Attachment cell      — file-type icon grid
 *   - Due-date cell        — calendar chip with overdue highlight
 *   - Status cell          — traffic-light dot + label
 */
